mapper.sql:
WHERE status = 'PUBLISHED'
AND category = #{category}

    AND (title LIKE CONCAT('%', #{keyword}, '%') OR summary LIKE CONCAT('%', #{keyword}, '%'))

mapper.select:
SELECT id, title, category, cover_url coverUrl, summary, published_at publishedAt
FROM showcase_item 
ORDER BY sort_order ASC, id DESC LIMIT #{pageSize} OFFSET #{offset}
